#!/usr/bin/env python
"""
Validation script to ensure our refactored code correctly addresses the feature envy smell.

This script checks:
1. That CalibratedClassifierCV no longer directly accesses _CalibratedClassifier internals
2. That _CalibratedClassifier encapsulates its own behavior properly
3. That the functionality is preserved
"""

import ast
import sys

def validate_no_direct_attribute_access(code):
    """Validate that CalibratedClassifierCV doesn't directly access _CalibratedClassifier internals."""

    # Parse the code into an AST
    tree = ast.parse(code)

    class DirectAccessChecker(ast.NodeVisitor):
        def __init__(self):
            self.issues = []

        def visit_For(self, node):
            # Look for loops over calibrated_classifiers_
            if (isinstance(node.target, ast.Name) and 
                'cal_clf' in node.target.id):
                # Check body for direct attribute access
                for stmt in node.body:
                    if isinstance(stmt, ast.If):
                        # Check condition for direct attribute access
                        self.check_attribute_access(stmt.test, node.lineno)
                    elif isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Call):
                        # Check function calls for attribute access
                        if isinstance(stmt.value.func, ast.Attribute):
                            self.check_method_call(stmt.value.func, node.lineno)

            self.generic_visit(node)

        def check_attribute_access(self, node, line_no):
            """Check if there's direct attribute access to cal_clf."""
            if isinstance(node, ast.Compare):
                for comparator in node.comparators:
                    if (isinstance(comparator, ast.Attribute) and 
                        'cal_clf' in comparator.attr):
                        self.issues.append(f"Line {line_no}: Direct access to cal_clf.{comparator.attr}")

        def check_method_call(self, node, line_no):
            """Check if there's direct method call on cal_clf internals."""
            if isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name):
                if 'cal_clf' in node.value.id:
                    # This might be okay if it's calling our new methods
                    if node.attr not in ['post_fit_processing', 'get_n_features_in', 'get_feature_names_in']:
                        self.issues.append(f"Line {line_no}: Direct method call on cal_clf.{node.attr}")

    checker = DirectAccessChecker()
    checker.visit(tree)
    return checker.issues

def main():
    # Read the refactored code
    with open('/workspace/project/scikit-learn/sklearn/calibration.py', 'r') as f:
        code = f.read()

    # Extract the _sync_calibrated_attributes method
    lines = code.split('\n')
    method_start = None
    method_end = None

    for i, line in enumerate(lines):
        if 'def _sync_calibrated_attributes' in line:
            method_start = i
        elif method_start is not None and line.startswith('    def ') and 'sync' not in line:
            method_end = i
            break

    if method_start is None:
        print("ERROR: Could not find _sync_calibrated_attributes method")
        return 1

    if method_end is None:
        method_end = len(lines)

    method_code = '\n'.join(lines[method_start:method_end])
    print("Found _sync_calibrated_attributes method:")
    print(method_code)
    print("\n" + "="*50 + "\n")

    # Validate that there's no direct attribute access
    issues = validate_no_direct_attribute_access(method_code)

    if issues:
        print("ISSUES FOUND:")
        for issue in issues:
            print(f"  - {issue}")
        return 1
    else:
        print("SUCCESS: No direct attribute access found!")
        print("The refactored code properly encapsulates _CalibratedClassifier behavior.")
        return 0

if __name__ == "__main__":
    sys.exit(main())
